  Pressable,
  Animated,
  Easing,
  Dimensions,
} from 'react-native';
import { UserBadge } from '@/types/badge';
import confetti from 'canvas-confetti';

interface BadgeCelebrationModalProps {
  visible: boolean;
  badge: UserBadge | null;
  onClose: () => void;
}

const { width: SCREEN_WIDTH } = Dimensions.get('window');

const BadgeCelebrationModal: React.FC<BadgeCelebrationModalProps> = ({
  visible,
  badge,
  onClose,
}) => {
  const scaleAnim = useRef(new Animated.Value(0)).current;
  const fadeAnim = useRef(new Animated.Value(0)).current;
  const hasTriggeredConfetti = useRef(false);

  useEffect(() => {
    if (visible && badge) {
      // Reset animation
      scaleAnim.setValue(0);
      fadeAnim.setValue(0);
      hasTriggeredConfetti.current = false;

      // Badge scale-in animation
      Animated.sequence([
        Animated.timing(fadeAnim, {
          toValue: 1,
          duration: 200,
          useNativeDriver: true,
        }),
        Animated.spring(scaleAnim, {
          toValue: 1,
          friction: 5,
          tension: 40,
          useNativeDriver: true,
        }),
      ]).start();

      // Trigger confetti animation
      if (!hasTriggeredConfetti.current) {
        hasTriggeredConfetti.current = true;
        triggerConfetti();
      }
    }
  }, [visible, badge]);

  const triggerConfetti = () => {
    // Create confetti burst from center
    const duration = 3000;
    const animationEnd = Date.now() + duration;
    const defaults = { startVelocity: 30, spread: 360, ticks: 60, zIndex: 0 };

    const randomInRange = (min: number, max: number) => {
      return Math.random() * (max - min) + min;
    };

    const interval: any = setInterval(() => {
      const timeLeft = animationEnd - Date.now();

      if (timeLeft <= 0) {
        return clearInterval(interval);
      }

      const particleCount = 50 * (timeLeft / duration);

      // Fire confetti from multiple positions
      confetti({
        ...defaults,
        particleCount,
        origin: { x: randomInRange(0.1, 0.3), y: Math.random() - 0.2 },
        colors: ['#4CAF50', '#FF9800', '#2196F3', '#FFC107', '#E91E63'],
      });
      confetti({
        ...defaults,
        particleCount,
        origin: { x: randomInRange(0.7, 0.9), y: Math.random() - 0.2 },
        colors: ['#4CAF50', '#FF9800', '#2196F3', '#FFC107', '#E91E63'],
      });
    }, 250);

    // Cleanup interval after duration
    setTimeout(() => clearInterval(interval), duration);
  };

  if (!badge || !badge.badge) {
    return null;
  }

  const badgeIcon = badge.badge.icon_url || '🏆';
  const isEmoji = !badge.badge.icon_url;

  return (
    <Modal
      visible={visible}
      transparent
      animationType="fade"
      onRequestClose={onClose}
      testID="badge-celebration-modal"
    >
      <Pressable
        style={styles.overlay}
        onPress={onClose}
        testID="celebration-overlay"
      >
        <Animated.View
          style={[
            styles.container,
            {
              opacity: fadeAnim,
              transform: [{ scale: scaleAnim }],
            },
          ]}
        >
          <Pressable onPress={() => {}} testID="celebration-content">
            {/* Badge Icon */}
            <View style={styles.badgeContainer} testID="badge-icon-container">
              {isEmoji ? (
                <Text style={styles.badgeEmoji} testID="badge-emoji">
                  {badgeIcon}
                </Text>
              ) : (
                <Image
                  source={{ uri: badgeIcon }}
                  style={styles.badgeImage}
                  testID="badge-image"
                />
              )}
            </View>

            {/* Title */}
            <Text style={styles.title} testID="celebration-title">
              🎉 New Badge Earned! 🎉
            </Text>

            {/* Badge Name */}
            <Text style={styles.badgeName} testID="badge-name">
              {badge.badge.name}
            </Text>

            {/* Badge Description */}
            <Text style={styles.description} testID="badge-description">
              {badge.badge.description}
            </Text>

            {/* Close Button */}
            <Pressable
              style={styles.button}
              onPress={onClose}
              testID="celebration-close-button"
            >
              <Text style={styles.buttonText}>Awesome!</Text>
            </Pressable>
          </Pressable>
        </Animated.View>
      </Pressable>
    </Modal>
  );
};

