// filepath: p2p-kids-marketplace/src/services/badgeNotifications.ts
// TASK: NOTIF-V2-004 - Badge Award Notifications
// Purpose: Service layer for badge notification logic

import { supabase } from '@/config/supabase';
import { UserBadge, Badge } from '@/types/badge';

export interface BadgeNotificationData {
  badge_id: string;
  badge_name: string;
  badge_icon: string;
  badge_description: string;
  category: string;
  deep_link: string;
}

export interface MilestoneNotificationData extends BadgeNotificationData {
  current_progress: number;
  threshold: number;
  remaining: number;
}

/**
 * Check badge milestones for a user and send "almost there" notifications
 * Milestone notifications are sent when user is close to earning next badge:
 * - Within 5 SP of next SP badge
 * - Within 2 trades of next trade badge
 * 
 * Deduplication: Only sends once per badge per 7 days
 * 
 * @param userId - User ID to check milestones for
 * @returns Success/failure result
 */
export const checkBadgeMilestones = async (
  userId: string
): Promise<{ success: boolean; error?: string }> => {
  try {
    const { error } = await supabase.rpc('check_badge_milestones', {
      p_user_id: userId,
    });

    if (error) {
      console.error('[badgeNotifications] Error checking milestones:', error);
      return { success: false, error: error.message };
    }

    return { success: true };
  } catch (err) {
    const error = err as Error;
    console.error('[badgeNotifications] Unexpected error:', error);
    return { success: false, error: error.message };
  }
};

/**
 * Fetch unread badge notifications for user
 * Used to display badge notifications in notification center
 * 
 * @param userId - User ID to fetch notifications for
 * @returns Array of badge notifications
 */
export const getBadgeNotifications = async (
  userId: string
): Promise<{ data: any[]; error?: string }> => {
  try {
    const { data, error } = await supabase
      .from('user_notifications')
      .select('*')
      .eq('user_id', userId)
      .eq('category', 'badges')
      .is('read_at', null)
      .order('created_at', { ascending: false });

    if (error) {
      console.error('[badgeNotifications] Error fetching notifications:', error);
      return { data: [], error: error.message };
    }

    return { data: data || [] };
  } catch (err) {
    const error = err as Error;
    console.error('[badgeNotifications] Unexpected error:', error);
    return { data: [], error: error.message };
  }
};

/**
 * Mark badge notification as read
 * 
 * @param notificationId - Notification ID to mark as read
 * @returns Success/failure result
 */
export const markBadgeNotificationRead = async (
  notificationId: string
): Promise<{ success: boolean; error?: string }> => {
  try {
    const { error } = await supabase
      .from('user_notifications')
      .update({ read_at: new Date().toISOString() })
      .eq('id', notificationId);

    if (error) {
      console.error('[badgeNotifications] Error marking notification as read:', error);
      return { success: false, error: error.message };
    }

    return { success: true };
  } catch (err) {
    const error = err as Error;
    console.error('[badgeNotifications] Unexpected error:', error);
    return { success: false, error: error.message };
  }
};

/**
 * Send push notification for badge award via Edge Function
 * This is called from the app when a new badge is awarded
 * 
 * @param userId - User ID who earned the badge
 * @param badge - Badge details
 * @returns Success/failure result
 */
export const sendBadgeAwardPushNotification = async (
  userId: string,
  badge: Badge
): Promise<{ success: boolean; error?: string }> => {
  try {
    const { data, error } = await supabase.functions.invoke('send-push-notification', {
      body: {
        userId,
        title: `New Badge Earned! ${badge.icon_url || '🏆'}`,
        body: `Congratulations! You earned the "${badge.name}" badge: ${badge.description}`,
        data: {
          badge_id: badge.id,
          badge_name: badge.name,
          category: 'badges',
          deep_link: '/profile/badges',
        },
        priority: 'high',
      },
    });

    if (error) {
      console.warn('[badgeNotifications] Error sending push notification:', error);
      return { success: false, error: error.message };
    }

    return { success: true };
  } catch (err) {
    const error = err as Error;
    console.warn('[badgeNotifications] Unexpected error sending push:', error);
    return { success: false, error: error.message };
  }
};

/**
 * Parse badge notification data from notification row
 * 
 * @param notification - Notification row from database
 * @returns Parsed badge notification data
 */
export const parseBadgeNotificationData = (
  notification: any
): BadgeNotificationData | MilestoneNotificationData | null => {
  try {
    if (!notification.data) {
      return null;
    }

    const data = typeof notification.data === 'string' 
      ? JSON.parse(notification.data) 
      : notification.data;

    return data as BadgeNotificationData | MilestoneNotificationData;
  } catch (err) {
    console.error('[badgeNotifications] Error parsing notification data:', err);
    return null;
  }
};

// File: p2p-kids-marketplace/src/hooks/useUserBadges.ts
// TASK BADGES-V2-009: Real-time subscription for user badges
// TASK NOTIF-V2-004: Badge celebration modal integration

import { useEffect, useState, useCallback, useRef } from 'react';
import { supabase } from '@/config/supabase';
import { UserBadge } from '@/types/badge';
import { sendBadgeAwardPushNotification, checkBadgeMilestones } from '@/services/badgeNotifications';

interface UseUserBadgesResult {
  badges: UserBadge[];
  loading: boolean;
  error: string | null;
  refresh: () => Promise<void>;
  newBadgeAwarded: UserBadge | null;
  clearNewBadge: () => void;
  showCelebration: boolean;
  setShowCelebration: (show: boolean) => void;
}

/**
 * Hook to fetch user badges and subscribe to real-time updates
 * 
 * Features:
 * - Fetches user's badges on mount
 * - Subscribes to real-time INSERT events on user_badges table
 * - Exposes newBadgeAwarded for celebration modals
 * - Automatically refreshes badges when new badge is awarded
 * 
 * Usage:
 * ```tsx
 * const { badges, loading, newBadgeAwarded, clearNewBadge } = useUserBadges(userId);
 * 
 * useEffect(() => {
 *   if (newBadgeAwarded) {
 *     showCelebrationModal(newBadgeAwarded);
 *     clearNewBadge();
 *   }
 * }, [newBadgeAwarded]);
 * ```
 */
export const useUserBadges = (userId: string | undefined): UseUserBadgesResult => {
  const [showCelebration, setShowCelebration] = useState(false);
  const [badges, setBadges] = useState<UserBadge[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newBadgeAwarded, setNewBadgeAwarded] = useState<UserBadge | null>(null);
  const channelRef = useRef<any>(null);
  const hasInitializedBadgeSnapshotRef = useRef(false);
  const latestBadgeIdRef = useRef<string | null>(null);
  const handledBadgeIdsRef = useRef<Set<string>>(new Set());

  const handleNewBadgeAwarded = useCallback(
    (badge: UserBadge) => {
      if (!badge?.id || handledBadgeIdsRef.current.has(badge.id)) {
        return;
      }

      handledBadgeIdsRef.current.add(badge.id);

      setBadges((prev) => {
        const exists = prev.some((b) => b.id === badge.id);
        return exists ? prev : [badge, ...prev];
      });

      setNewBadgeAwarded(badge);
      setShowCelebration(true);

      if (userId && badge.badge) {
        sendBadgeAwardPushNotification(userId, badge.badge).catch((err) => {
          console.warn('Failed to send badge push notification:', err);
        });
      }

      if (userId) {
        checkBadgeMilestones(userId).catch((err) => {
          console.warn('Failed to check badge milestones:', err);
        });
      }
    },
    [userId]
  );

  const loadBadges = useCallback(async () => {
    if (!userId) {
      setBadges([]);
      setLoading(false);
      return;
    }

    try {
      setError(null);
      const { data, error: fetchError } = await supabase
        .from('user_badges')
        .select('*, badge:badges(*)')
        .eq('user_id', userId)
        .order('awarded_at', { ascending: false });

      if (fetchError) throw fetchError;

      const fetchedBadges = (data || []) as UserBadge[];
      setBadges(fetchedBadges);

      const latestBadge = fetchedBadges[0] || null;

      if (!hasInitializedBadgeSnapshotRef.current) {
        hasInitializedBadgeSnapshotRef.current = true;
        latestBadgeIdRef.current = latestBadge?.id || null;
      } else if (latestBadge?.id && latestBadge.id !== latestBadgeIdRef.current) {
        latestBadgeIdRef.current = latestBadge.id;
        handleNewBadgeAwarded(latestBadge);
      }
    } catch (err: any) {
      console.error('Error loading user badges:', err);
      setError(err.message || 'Failed to load badges');
    } finally {
      setLoading(false);
    }
  }, [userId, handleNewBadgeAwarded]);

  const refresh = useCallback(async () => {
    setLoading(true);
    await loadBadges();
  }, [loadBadges]);

  const clearNewBadge = useCallback(() => {
    setNewBadgeAwarded(null);
    setShowCelebration(false);
  }, []);

  useEffect(() => {
    if (!userId) {
      setLoading(false);
      return;
    }

    // Initial load
    loadBadges();

    // Setup real-time subscription
    const channelName = `user_badges_${userId}`;
    const channel = supabase
      .channel(channelName)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'user_badges',
          filter: `user_id=eq.${userId}`,
        },
        async (payload) => {
          console.log('🎉 New badge awarded via real-time:', payload);

          // Fetch the newly awarded badge with full details
          try {
            const { data: newBadge, error: fetchError } = await supabase
              .from('user_badges')
              .select('*, badge:badges(*)')
              .eq('id', payload.new.id)
              .single();

            if (fetchError) {
              console.error('Error fetching new badge details:', fetchError);
              // Fallback: reload all badges
              await loadBadges();
              return;
            }

            handleNewBadgeAwarded(newBadge as UserBadge);
          } catch (err) {
            console.error('Error handling new badge:', err);
            // Fallback: reload all badges
            await loadBadges();
          }
        }
      )
      .subscribe();

    channelRef.current = channel;

    // Fallback polling path: handles environments where realtime events are delayed/missed.
    const pollInterval = setInterval(() => {
      loadBadges().catch((err) => {
        console.warn('Badge polling refresh failed:', err);
      });
    }, 4000);

    // Cleanup
    return () => {
      setShowCelebration(false);
      clearInterval(pollInterval);
      hasInitializedBadgeSnapshotRef.current = false;
      latestBadgeIdRef.current = null;
      handledBadgeIdsRef.current.clear();
      if (channelRef.current) {
        supabase.removeChannel(channelRef.current);
        channelRef.current = null;
      }
    };
  }, [userId, loadBadges, handleNewBadgeAwarded]);

  return {
    badges,
    loading,
    error,
    refresh,
    newBadgeAwarded,
    clearNewBadge,
    showCelebration,
    setShowCelebration,
  };
};

