      }

      const runSideEffects = options?.runSideEffects ?? true;

      handledBadgeIdsRef.current.add(badge.id);
      currentCelebrationBadgeIdRef.current = badge.badge_id || badge.badge?.id || null;

      setBadges((prev) => {
        const exists = prev.some((b) => b.id === badge.id);
